[51] {"id": "d658e26a-e351-4bca-824e-f346deaa87c5", "contains": [], "title": "Potenzen mit natürlichen Exponenten deuten und berechnen", "description": "Die lernende Person kann bei Potenzen a^n mit ganzzahliger Basis a und natürlichem Exponenten n ≥ 1 Basis und Exponent unterscheiden, a^n als Produkt aus n gleichen Faktoren deuten, den Wert berechnen und das Ergebnis an der Faktorstruktur prüfen.", "descriptionEn": "For powers a^n with integer base a and natural exponent n ≥ 1, the learner can distinguish base and exponent, interpret a^n as a product of n equal factors, calculate its value, and check the result against the factor structure.", "requires": ["cafd6520-c4af-4109-9863-cc49ba6fad4d"]}
[52] {"id": "d6c3fb37-ece6-5b56-9221-1eeb21845877", "title": "Umfang und Flächeninhalt unterscheiden und anwenden", "description": "Die lernende Person kann Umfang als Länge des Randes und Flächeninhalt als Maß der bedeckten Fläche unterscheiden, in einfachen Sachsituationen die passende Größe und Formel wählen und Ergebnisse mit geeigneten Einheiten deuten.", "descriptionEn": "The learner can distinguish perimeter as the length of a boundary from area as the measure of a covered region, choose the appropriate quantity and formula in simple contexts, and interpret results using suitable units.", "contains": [], "requires": ["ca623958-c204-5d1b-bdd0-3f76765674cb"]}
[53] {"id": "d825f7ce-e19b-594a-8181-eff199c21d93", "title": "Vier Grundrechenarten mit natürlichen Zahlen in Sachsituationen auswählen und prüfen", "description": "Die lernende Person kann in überschaubaren Sach- und Rechensituationen die passende der vier Grundrechenarten mit natürlichen Zahlen auswählen, einen geeigneten Rechenweg begründen und ausführen sowie die Größenordnung des Ergebnisses mit einem Überschlag prüfen.", "descriptionEn": "The learner can select the appropriate one of the four arithmetic operations with natural numbers in straightforward contextual and numerical situations, justify and carry out a suitable calculation path, and check the result's order of magnitude using an estimate.", "contains": [], "requires": ["9ef6c4fa-b97a-5d7a-86c1-96690f02d916"]}
[54] {"id": "d98849c7-bd0b-50d4-90aa-6293a3adb211", "title": "Vierecke anhand ihrer Eigenschaften einordnen und begründen", "description": "Die lernende Person kann Quadrat, Rechteck, Parallelogramm, Raute, Drachenviereck und Trapez anhand ihrer Eigenschaften erkennen, darstellen und hierarchisch einordnen; dabei verwendet sie für Trapeze die inklusive Definition mit mindestens einem Paar paralleler Gegenseiten und begründet Mehrfachzuordnungen.", "descriptionEn": "The learner can identify, represent, and hierarchically classify squares, rectangles, parallelograms, rhombi, kites, and trapezoids from their properties, using the inclusive definition of a trapezoid as having at least one pair of opposite parallel sides and justifying multiple classifications.", "contains": [], "requires": ["2231c29b-eb4e-51ae-9cb1-eb033bf16099", "2331caf2-ccb2-5492-9fc6-48763b848bae"]}
[55] {"id": "e331a425-e9c6-46eb-89cb-dedf72857974", "contains": [], "title": "Große Zahlen mit Zehnerpotenzen darstellen und deuten", "description": "Die lernende Person kann große natürliche Zahlen mithilfe der Stellenwertstruktur zwischen Dezimalschreibweise und Darstellungen durch Zehnerpotenzen mit nichtnegativen Exponenten wechseln, ihre Größenordnung am Exponenten der größten Zehnerpotenz deuten, die die Zahl nicht überschreitet, und die Darstellung in einfachen Sachzusammenhängen auf Plausibilität prüfen.", "descriptionEn": "The learner can use place-value structure to switch large natural numbers between decimal notation and representations using powers of ten with non-negative exponents, interpret their order of magnitude from the exponent of the greatest power of ten that does not exceed the number, and check the representation for plausibility in simple contexts.", "requires": ["d658e26a-e351-4bca-824e-f346deaa87c5"]}
[56] {"id": "e4b38061-1f28-43ad-8371-a3e7c0e81856", "title": "Gleichmäßig beschleunigte Bewegung und Beschleunigung", "description": "Die lernende Person kann das Modell der gleichmäßig beschleunigten Bewegung mit konstanter Beschleunigung erläutern und in t-s-, t-v- und t-a-Darstellungen beschreiben.", "descriptionEn": "The learner can explain the model of uniformly accelerated motion with constant acceleration and describe it using time-position, time-velocity, and time-acceleration representations.", "contains": [], "requires": ["bf8517a9-142b-5789-826a-767f3b277998", "c65ecabf-d00b-4e2d-99ae-b64692325ffb", "87c55be5-06a9-41e2-a0d4-c60f7c8b8078", "1e459a1b-4159-5049-84eb-9928129c1610"]}
[57] {"id": "e82d8d3a-9012-5482-afe6-ab0d727a49bb", "title": "Rechnungen mit Umkehroperationen überprüfen", "description": "Die lernende Person kann Ergebnisse einfacher Rechnungen mithilfe passender Umkehroperationen überprüfen und Fehler in Rechenwegen erkennen.", "descriptionEn": "The learner can check results of simple calculations using suitable inverse operations and identify errors in calculation paths.", "contains": [], "requires": ["d825f7ce-e19b-594a-8181-eff199c21d93"]}
[58] {"id": "ec9f2ed4-c9e6-5fb3-a073-75b53127e55d", "title": "Dichtheit der rationalen Zahlen erläutern", "description": "Die lernende Person kann erläutern, dass zwischen zwei verschiedenen rationalen Zahlen stets weitere rationale Zahlen liegen, durch wiederholte Mittelwertbildung beliebig viele davon konstruieren und damit die Dichtheit begründen.", "descriptionEn": "The learner can explain that further rational numbers always lie between any two distinct rational numbers, construct arbitrarily many of them by repeatedly taking midpoints, and thereby justify density.", "contains": [], "requires": ["02013455-72a0-5213-9509-ed77f7ede62b", "f6b13b8e-1ecd-5420-905d-21290aa996a6"]}
[59] {"id": "ee48e811-4c9c-5080-9836-8403fc9f0810", "title": "Rationale Zahlen multiplizieren und dividieren", "description": "Die lernende Person kann nicht ganze rationale Zahlen, insbesondere Brüche und Dezimalzahlen, in verschiedenen Darstellungsformen multiplizieren und dividieren, dabei tragfähige Operationsvorstellungen nutzen und Rechenvorteile gezielt einsetzen.", "descriptionEn": "The learner can multiply and divide non-integer rational numbers, especially fractions and decimals, in different representations, use solid operation concepts, and apply calculation advantages purposefully.", "contains": [], "requires": ["a4c2b831-02f0-5d55-a300-7823a71352c4", "5d1decb2-b01b-5c85-88fc-9fc255ff9776"]}
[60] {"id": "f08d06dc-139d-5fd2-892c-8cc919b1e4fc", "title": "Terme mit Variablen lesen und deuten", "description": "Die lernende Person kann Terme mit Variablen lesen, ihre Bestandteile und Rechenstruktur benennen und ihre Bedeutung in einfachen Kontexten erklären.", "descriptionEn": "The learner can read expressions with variables, identify their components and operational structure, and explain their meaning in simple contexts.", "contains": [], "requires": ["5bba4ec2-3781-4624-8b62-e24b38f7f76e"]}
[61] {"id": "f2e42af5-67a6-477e-82ea-e65b09cc6cb3", "title": "Größen und Einheiten vergleichen und umrechnen", "description": "Die lernende Person kann für alltagsnahe Größen passende Einheiten auswählen, Größenangaben sicher in gleichartige Einheiten umrechnen, dabei anhand des Einheitenverhältnisses begründen, warum die dargestellte Größe unverändert bleibt, und Messergebnisse in einer gemeinsamen Einheit sinnvoll vergleichen.", "descriptionEn": "The learner can choose suitable units for everyday quantities, reliably convert measurements into equivalent units, justify the unchanged quantity from the relationship between the units, and compare measurement results meaningfully in a common unit.", "contains": [], "requires": ["54148506-c23f-41b8-959b-068dd194cf15", "5d1decb2-b01b-5c85-88fc-9fc255ff9776", "2ae76eae-799c-463e-9ec9-82327f8209a8", "b5de0574-93ed-409c-80ee-312211420cd6"]}
[62] {"id": "f3167cab-bb23-4bb9-8a27-22e3c5015d44", "title": "Proportionale Funktionen als Ursprungsgeraden deuten und darstellen", "description": "Die lernende Person kann proportionale Funktionen in Tabellen und als Ursprungsgeraden in Graphen darstellen und deuten und dabei erläutern, dass bei Eingabewerten ungleich null der konstante Quotient aus Ausgabe- und Eingabewert der Steigung der Geraden entspricht.", "descriptionEn": "The learner can represent and interpret proportional functions in tables and as lines through the origin in graphs and explain that, for nonzero inputs, the constant ratio of output to input corresponds to the slope of the line.", "contains": [], "requires": ["c1f50bcc-7848-4e49-b9de-0ec030cc6bca"]}
[63] {"id": "f6a54a49-b6cf-4ab7-a185-aa08bfcb6c97", "title": "Bruchdarstellungen verwenden und wechseln", "description": "Die lernende Person kann denselben Bruchwert bildlich, verbal, geometrisch und algebraisch darstellen, Informationen zwischen diesen Darstellungen übertragen und begründen, warum der Wert beim Wechsel erhalten bleibt.", "descriptionEn": "The learner can represent the same fractional value visually, verbally, geometrically, and algebraically, transfer information between these representations, and justify why the value is preserved when switching.", "contains": [], "requires": ["6b0075bb-f71c-59f6-ab98-fb894568cc26"]}
[64] {"id": "f6b13b8e-1ecd-5420-905d-21290aa996a6", "title": "Rationale Zahlen an der Zahlengeraden darstellen und ordnen", "description": "Die lernende Person kann positive und negative nicht ganze rationale Zahlen, insbesondere Bruch- und Dezimalzahlen, auf einer passend skalierten Zahlengeraden darstellen, begründet ordnen und wertgleiche Darstellungen demselben Punkt zuordnen.", "descriptionEn": "The learner can represent positive and negative non-integer rational numbers, especially fractions and decimals, on a suitably scaled number line, order them with justification, and assign equivalent representations to the same point.", "contains": [], "requires": ["d07ef7b1-8bd2-56e0-9e74-d90c3c3e02fe"]}
[65] {"id": "fe07241a-b779-5f35-a82d-7aa51ae74f42", "title": "Natürliche Zahlen runden", "description": "Die lernende Person kann natürliche Zahlen auf eine vorgegebene oder zum Sachzusammenhang passende Stelle runden und die Bedeutung des entstehenden Näherungswerts erläutern.", "descriptionEn": "The learner can round natural numbers to a given place or to a place appropriate to the context and explain the meaning of the resulting approximate value.", "contains": [], "requires": ["624764d6-becd-5f9b-ada3-0d4f9d143073"]}

